using Fm27Editor.Core.Players;

namespace Fm27Editor.Core.Tests;

public class FutureTransferContractTemplateTests
{
    // Both fixtures are captured RAM bytes from Rice before and after FMRTE arranged the transfer.
    [Fact]
    public void BuildsCapturedRiceContract()
    {
        var source = Convert.FromHexString("");
        var expected = Convert.FromHexString("");
        var result = FutureTransferContractTemplate.Build(source, 0x17424F793A0, new(2026, 9, 30), new(2027, 1, 1),
            0x17428DFFBF0, 24, 0x17428DFFAA0, 32);
        Assert.Equal(expected, result);
    }

    [Fact]
    public void PreservesEmptyAdditionalVectorInCapturedWoodContract()
    {
        var source = Convert.FromHexString("");
        var expected = Convert.FromHexString("");
        var result = FutureTransferContractTemplate.Build(source, 0x17424F53A08, new(2026, 9, 30), new(2027, 12, 31),
            0x17428DFF980, 24, 0, 0);
        Assert.Equal(expected, result);
    }
}
